input.newString:
async function searchForTarget(
  target: ResearchTarget,
  settings: ApparatusSettings,
): Promise<SearchOutcome> {
  const query = target.query;
  const context = `The draft says: "${target.anchor}" — ${target.reason}`;
  const configured = await searchWithConfiguredProvider(
    query,
    context,
    settings,
  );
  if (configured) return configured;
  // Hosted fallback: a locally-configured provider wasn't usable or chosen.
  if (!activeClient) {
    return {
      ok: false,
      message:
        "No research provider is configured — add one in Settings, or sign in for the built-in research service.",
    };
  }
  try {
    const res = (await activeClient.action(api.research.searchSources, {
      query,
      context,
    })) as { results?: Source[]; provider?: string };
    return {
      ok: true,
      provider: res.provider ?? "hosted",
      results: Array.isArray(res.results) ? res.results : [],
    };
  } catch (err) {
    return {
      ok: false,
      message: errorMessage(err, "The built-in research service failed."),
    };
  }
}

async function searchWithConfiguredProvider(
  query: string,
  context: string,
  settings: ApparatusSettings,
): Promise<SearchOutcome | null> {
  switch (settings.researchProvider) {
    case "tinyfish":
      return searchTinyFish(query, context, settings);
    case "model-web-search":
      return searchModelEndpoint(query, context, settings);
    case "web-mcp":
      return searchWebMcp(query, context, settings);
    case "hosted":
    default:
      return null;
  }
}

async function searchTinyFish(
  query: string,
  context: string,
  settings: ApparatusSettings,
): Promise<SearchOutcome | null> {
  const key = settings.tinyFishApiKey.trim();
  if (!key) {
    return {
      ok: false,
      message: "No TinyFish API key — add one in Settings to search claims.",
    };
  }
  try {
    const res = await fetch(TINYFISH_SEARCH_URL, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        authorization: `Bearer ${key}`,
      },
      body: JSON.stringify({
        query,
        context,
        num_results: settings.tinyFishMaxResults,
      }),
    });
    if (!res.ok) {
      return {
        ok: false,
        message: `TinyFish returned HTTP ${res.status}. Check the key or retry.`,
      };
    }
    const data = (await res.json()) as { results?: unknown };
    const results = normalizeSources(data.results, settings.tinyFishMaxResults);
    return { ok: true, provider: "tinyfish:byok", results };
  } catch (err) {
    return { ok: false, message: errorMessage(err, "TinyFish search failed.") };
  }
}

async function searchModelEndpoint(
  query: string,
  context: string,
  settings: ApparatusSettings,
): Promise<SearchOutcome | null> {
  const aiSettings = await loadAiSettingsFromIdb();
  if (!aiSettings) {
    return {
      ok: false,
      message: "No AI provider configured for the search model.",
    };
  }
  try {
    const res = await runClientResearchWebSearch(
      {
        query,
        context,
        maxResults: settings.tinyFishMaxResults,
        instructions:
          "Only return sources that demonstrably support the quoted claim. Prefer the exact source of the quote when the query asks for one.",
      },
      aiSettings,
    );
    return {
      ok: true,
      provider: res?.provider ?? "model-web-search",
      results: (res?.results as Source[]) ?? [],
    };
  } catch (err) {
    return {
      ok: false,
      message: errorMessage(err, "Model web search failed."),
    };
  }
}

async function searchWebMcp(
  query: string,
  context: string,
  settings: ApparatusSettings,
): Promise<SearchOutcome | null> {
  const endpoint = settings.mcpEndpointUrl.trim();
  const toolName = settings.mcpToolName.trim() || "search";
  if (!endpoint) {
    return {
      ok: false,
      message: "No MCP endpoint in Settings — add one to search claims.",
    };
  }
  try {
    const headers: Record<string, string> = {
      "content-type": "application/json",
    };
    const token = settings.mcpBearerToken.trim();
    if (token) headers.authorization = `Bearer ${token}`;
    const res = await fetch(endpoint, {
      method: "POST",
      headers,
      body: JSON.stringify({
        jsonrpc: "2.0",
        id: `twyne-${Date.now()}`,
        method: "tools/call",
        params: {
          name: toolName,
          arguments: {
            query,
            context,
            max_results: settings.tinyFishMaxResults,
          },
        },
      }),
    });
    if (!res.ok) {
      return {
        ok: false,
        message: `MCP tool (${toolName}) returned HTTP ${res.status}.`,
      };
